import {createRoot} from 'react-dom/client'
import App from './App'
import { createBrowserRouter } from 'react-router'
import { RouterProvider } from 'react-router-dom'
import AllProperties from './Properties/AllProperties'
import ScrollToTop from 'react-scroll-to-top'
import AllProperty from './PropertyDetails/AllProperty'
import AllContact from './Contact/AllContact'
import {AllData} from './Data/AllData'
import AllProducts from './Products/AllProducts'
import AllCart from './Cart/AllCart'
import Details from './Details/Details'
const exchange = createBrowserRouter([
  {
    path: '/',
    element: <App />
  },
  {
    path: '/Properties',
    element: <AllProperties />
  },
  {
    path:'/PropertyDetails',
    element:<AllProperty/>
  },
  {
    path:'/Contact',
    element:<AllContact/>
  },
  {
    path:'/Products',
    element:<AllProducts/>
  },
  {
    path:'/Cart',
    element:<AllCart/>
  },
  {
    path:'/Products/:id',
    element:<Details/>
  },

])

createRoot(document.getElementById('root')).render(
  <>
    <AllData>
      <RouterProvider router={exchange} />
      <ScrollToTop smooth />
    </AllData>
  </>
)
