import { useContext } from "react";
import { apiValue } from "../Data/AllData";
import { Link } from "react-router";
import { useCart, CartProvider } from "react-use-cart";
import { useState } from "react";

function Page() {
  const api = useContext(apiValue);
  const { addItem } = useCart();
  const [search, setSearch] = useState("Show All");
  function getValue(event) {
    setSearch(event.target.innerHTML);
  }

  return (
    <>
      <div>
        <div className="section properties">
          <div className="container">
            <ul className="properties-filter">
              <li>
                <button className="btn btn-block" onClick={getValue}>
                  Show All
                </button>
              </li>
              <li>
                <button className="btn btn-block" onClick={getValue}>
                  beauty
                </button>
              </li>
              <li>
                <button className="btn btn-block" onClick={getValue}>
                  fragrances
                </button>
              </li>
              <li>
                <button className="btn btn-block" onClick={getValue}>
                  furniture
                </button>
              </li>
              <li>
                <button className="btn btn-block" onClick={getValue}>
                  groceries
                </button>
              </li>
            </ul>
          </div>
        </div>
      </div>
      <div className="section properties">
        <div className="container">
          <div className="row properties-box">
            {api.map((element) => {
              return search === "Show All" ? (
                <div className="col-lg-4 col-md-6 align-self-center mb-30 properties-items col-md-6 adv">
                  <div className="item">
                    <a href="property-details.html">
                      <img src={element.images[0]} alt="" />
                    </a>
                    <span className="category">{element.category}</span>
                    <h6>{Math.ceil(element.price)}$</h6>
                    <h4>
                      <a href="property-details.html">{element.title}</a>
                    </h4>
                    <ul>
                      <li>
                        Stock: <span>{element.stock}</span>
                      </li>
                      <li>
                        Rating: <span>{element.rating}</span>
                      </li>
                      <li>
                        Id: <span>{element.id}</span>
                      </li>
                    </ul>
                    <div className="main-button">
                      <Link
                        className="bot w-100 my-2"
                        to={`/products/${element.id}`}
                      >
                        Details
                      </Link>
                      <button
                        className="bot w-100 border-0"
                        onClick={() => addItem(element)}
                      >
                        Add to Cart
                      </button>
                    </div>
                  </div>
                </div>
              ) : element.category == search ? (
                <div className="col-lg-4 col-md-6 align-self-center mb-30 properties-items col-md-6 adv">
                  <div className="item">
                    <a href="property-details.html">
                      <img src={element.images[0]} alt="" />
                    </a>
                    <span className="category">{element.category}</span>
                    <h6>{Math.ceil(element.price)}$</h6>
                    <h4>
                      <a href="property-details.html">{element.title}</a>
                    </h4>
                    <ul>
                      <li>
                        Stock: <span>{element.stock}</span>
                      </li>
                      <li>
                        Rating: <span>{element.rating}</span>
                      </li>
                      <li>
                        Id: <span>{element.id}</span>
                      </li>
                    </ul>
                    <div className="main-button">
                      <Link
                        className="bot w-100 my-2"
                        to={`/products/${element.id}`}
                      >
                        Details
                      </Link>
                      <button
                        className="bot w-100 border-0"
                        onClick={() => addItem(element)}
                      >
                        Add to Cart
                      </button>
                    </div>
                  </div>
                </div>

              ): null;
            })}
          </div>
        </div>
      </div>
    </>
  );
}

function Show() {
  return (
    <CartProvider>
      <Page />
    </CartProvider>
  );
}

export default Show;
