import { CartProvider, useCart } from "react-use-cart";
import AllComponents from "../Components/AllComponents";
import { Link } from "react-router";
function Cart() {
  const {
    items,
    totalUniqueItems,
    updateItemQuantity,
    removeItem,
    totalItems,
    cartTotal,
    isEmpty,
    emptyCart,
  } = useCart();

  if (isEmpty) {
    return (
      <div className="text-center mt-4">
        <h2>Your cart is empty</h2>
        <img className="w-25" src="/assets/images/emptycart.png" />
      </div>
    );
  } else {
    return (
      <>
        <div className="container">
          <table id="cart" className="table table-hover table-condensed">
            <thead>
              <tr>
                <th style={{ width: "50%" }}>Product</th>
                <th style={{ width: "10%" }}>Price</th>
                <th style={{ width: "8%" }}>Quantity</th>
                <th style={{ width: "22%" }} className="text-center">
                  Subtotal
                </th>
                <th>Operation</th>
              </tr>
            </thead>
            <tbody>
              {items.map((element) => {
                return (
                  <tr>
                    <td data-th="Product">
                      <div className="row">
                        <div className="col-sm-2 hidden-xs">
                          <img
                            src={element.images[0]}
                        alt="..."
                        className="img-responsive"
                      />
                    </div>
                    <div className="col-sm-10">
                      <h4 className="nomargin">{element.title}</h4>
                    </div>
                  </div>
                </td>
                <td data-th="Price">{element.price}$</td>
                <td data-th="Quantity">
                  {element.quantity}
                </td>
                <td data-th="Subtotal" className="text-center">
                  ${ Math.ceil(element.price * element.quantity)}
                </td>
                <td className="actions" data-th="">
                  <button className="btn btn-success w-100" onClick={() => updateItemQuantity(element.id, element.quantity + 1)}>
                    <i class="fa-duotone fa-thin fa-plus"></i>
                  </button>
                  <button className="btn btn-info w-100 my-2" onClick={() => updateItemQuantity(element.id, element.quantity - 1)}>
                    <i class="fa-notdog-duo fa-solid fa-minus"></i>
                  </button>
                  <button className="btn btn-danger w-100" onClick={() => removeItem(element.id)}>
                    <i class="fa-notdog-duo fa-solid fa-trash"></i>
                  </button>
                </td>
              </tr>
              );
              })}
            </tbody>
            <tfoot>
              <tr className="visible-xs">
                <td className="text-center">
                  <strong>All Unique Items : {totalUniqueItems}</strong>
                </td>
              </tr>
              <tr>
                <td>
                  <Link to="/products" className="btn btn-warning">
                    <i className="fa fa-angle-left" /> Continue Shopping
                  </Link>
                </td>
                <td colSpan={2} className="hidden-xs" />
                <td className="hidden-xs text-center">
                  <strong>Total $ {Math.ceil(cartTotal)}</strong>
                </td>
                <td>
                  <button className="btn btn-danger btn-block" onClick={() => emptyCart()}>
                    Clear Cart
                  </button>
                </td>
              </tr>
            </tfoot>
          </table>
        </div>
      </>
    );
  }
}

function AllCart() {
  return (
    <CartProvider>
      <AllComponents />
      <br />
      <br />
      <br />
      <Cart />
    </CartProvider>
  );
}

export default AllCart;
