 
import { useEffect, useState } from "react";
import { Link, useParams } from "react-router"
import axios from "axios";
import { CartProvider, useCart } from "react-use-cart";
import AllComponents from "../Components/AllComponents";

function Page(){
    const [text,setText] = useState({})
    const {id} = useParams();
    useEffect(() => {
      axios.get(`https://dummyjson.com/products/${id}`)
          .then(
              (element) => setText(element.data)
          )
    },[]);
    const {addItem} = useCart();
    return(
        <div className='container'>
            <div className='row text-center d-flex align-content-center'>
                <div className="col-md-6 mt-2">
                    <img src={text.images} className="w-100"/>
                </div>
                <div className="col-md-6 mt-5 p-5">
                        <h2>{text.title}</h2>
                        <p>brand: {text.brand}</p>
                        <p>category: {text.category}</p>
                        <p>Price: {text.price}$</p>
                        <p>discountPercentage: {text.discountPercentage}$</p>
                        <p>rating of 5: {text.rating}</p>
                        <p>stock: {text.stock}</p>
                        <button onClick={() => addItem(text)} className="btn btn-dark w-100 my-2">Add to cart</button>
                        <Link to="/Products" className="btn btn-dark w-100 ">Back</Link>
                </div>
            </div>
        </div>
    )
}

function Items() {
  return (
    <CartProvider>
        <AllComponents/>
        <br/>
        <br/>
        <br/>
        <Page/>
    </CartProvider>
  )
}

export default Items